// Generated by Cypress Author on 2026-10-08.
import { Box } from '@mui/material';
import type { ListeningActivityItem } from '../../../../backend/src/types/api';
import ListeningTrack from '../../../src/components/ListeningTrack';

const track: ListeningActivityItem = {
  trackId: 'test-track', name: 'Dreams', artists: ['Fleetwood Mac'],
  albumCoverUrl: '/test-album-cover.svg', durationMs: 257000,
  // Local time keeps the rendered listening time stable across runner timezones.
  playedAt: '2026-10-08T14:35:00',
};

describe('ListeningTrack', () => {
  beforeEach(() => {
    // Avoid the browser reusing the previous test's image without a network request.
    cy.intercept('GET', '/test-album-cover.svg', { fixture: 'album-cover.svg', headers: { 'content-type': 'image/svg+xml', 'cache-control': 'no-store' } }).as('cover');
  });

  it('track with cover → shows song, performer, duration and listening time', () => {
    cy.mount(<Box sx={{ width: 900, p: 2 }}><ListeningTrack track={track} /></Box>);
    cy.contains('h4', 'Dreams').should('be.visible');
    cy.contains('Fleetwood Mac').should('be.visible');
    cy.contains('4:17').should('be.visible');
    cy.get('time').should('have.attr', 'datetime', track.playedAt);
    cy.get('time').should('contain.text', new Date(track.playedAt).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }));
    cy.wait('@cover');
    cy.get('img').should('be.visible').and(($image) => {
      expect(($image[0] as HTMLImageElement).naturalWidth).to.be.greaterThan(0);
    });
    cy.get('[data-cy="listening-track"]').matchImage();
  });

  it('missing album cover → shows fallback and an hour-long duration', () => {
    cy.mount(<Box sx={{ width: 900, p: 2 }}><ListeningTrack track={{ ...track, albumCoverUrl: null, durationMs: 3723000 }} /></Box>);
    cy.get('[role="img"]').should('have.attr', 'aria-label', 'Album cover unavailable');
    cy.contains('1:02:03').should('be.visible');
    cy.get('[data-cy="listening-track"]').matchImage();
  });

  it('mobile long song and multiple performers → keeps every detail readable', () => {
    cy.viewport(390, 844);
    cy.mount(<Box sx={{ p: 2 }}><ListeningTrack track={{ ...track, name: 'A song for all the little moments that stay with us', artists: ['The Midnight', 'A very long featured performer name', 'Another artist'] }} /></Box>);
    cy.contains('h4', 'A song for all the little moments that stay with us').should('be.visible');
    cy.contains('Another artist').should('be.visible');
    cy.get('time').should('be.visible');
    cy.wait('@cover');
    cy.get('img').should(($image) => {
      expect(($image[0] as HTMLImageElement).naturalWidth).to.be.greaterThan(0);
    });
    cy.get('[data-cy="listening-track"]').matchImage();
  });
});
